{
	if (_is_global_invalid()) {
		const CanvasItem* pi = get_parent_item();
		if (pi) {
			global_transform = pi->get_global_transform_const() * get_transform();
		}
		else {
			global_transform = get_transform();
		}
	}

	return global_transform;
}

