Rect2 Viewport::get_visible_rect() const
{
	ERR_READ_THREAD_GUARD_V(Rect2());
	Rect2 r;

	if (size == Size2()) {
		r = Rect2(Point2(), DisplayServer::window_get_size());
	}
	else {
		r = Rect2(Point2(), size);
	}

	if (size_2d_override != Size2()) {
		r.size = size_2d_override;
	}
	return r;
}

