	ERR_FAIL_UNSIGNED_INDEX_V((uint32_t)p_track, tracks.size(), String());
	const Track* t = tracks[p_track];
	ERR_FAIL_COND_V(t->type != TYPE_METHOD, String());

	ERR_FAIL_UNSIGNED_INDEX_V((uint32_t)p_key_idx, t->methods.size(), String());

