void SkyMaterial::set_exposure_value(float p_exposure)
{
	set_energy_multiplier(Math::pow(2.0f, p_exposure));
}

float SkyMaterial::get_exposure_value() const
{
	return Math::log(get_energy_multiplier()) / Math::log(2.0f);
}

