void CodeHighlighter::update_cache()
{
	clear_highlighting_cache();

	if (text_edit == nullptr) {
		return;
	}
	_update_cache();
}

void CodeHighlighter::set_text_edit(TextEdit* p_text_edit) { text_edit = p_text_edit; }

