void Environment::set_sdfgi_cascades(int p_cascades)
{
	ERR_FAIL_COND_MSG(p_cascades < 1 || p_cascades > 8,
		"Invalid number of SDFGI cascades (must be between 1 and 8).");
	sdfgi_cascades = p_cascades;
	_update_sdfgi();
}

