Skeleton3D::Skeleton3D() {}

Skeleton3D::~Skeleton3D()
{
	// Some skins may remain bound.
	for (SkinReference* E : skin_bindings) {
		E->skeleton_node = nullptr;
	}
}

void Skeleton3D::_update_process_order() const {}

