	Ref<LightmapGIData> light_data;
	Node* last_owner = nullptr;

	struct LightsFound
	{
		Transform3D xform;
		Light3D* light = nullptr;
	};

	struct AreaLightAtlasTexture
	{
		Rect2 texture_rect;
		float max_mipmap;
	};

