	case DATA_FORMAT_BC3_UNORM_BLOCK:
	case DATA_FORMAT_BC3_SRGB_BLOCK:
		return 16;
	case DATA_FORMAT_BC4_UNORM_BLOCK:
	case DATA_FORMAT_BC4_SNORM_BLOCK:
