	case DATA_FORMAT_BC5_UNORM_BLOCK:
	case DATA_FORMAT_BC5_SNORM_BLOCK:
		return 16;
	case DATA_FORMAT_BC6H_UFLOAT_BLOCK:
	case DATA_FORMAT_BC6H_SFLOAT_BLOCK:
