void NavObstacle2D::set_map(NavMap2D* p_map)
{
	if (map == p_map) {
		return;
	}

	cancel_sync_request();

	if (map) {
		map->remove_obstacle(this);
		if (agent) {
			agent->set_map(nullptr);
		}
	}

	map = p_map;
	obstacle_dirty = true;

	if (map) {
		map->add_obstacle(this);
		internal_update_agent();

		request_sync();
	}
}

